def main():
    names = ["Eric", "Arnold", "Alice", "Peter"]
    heights = ["tall", "very short", "average", "short"]
    drinks = ["tea", "coffee", "water", "milk"]
    children = ["Fred", "Meredith", "Bella", "Samantha"]
    mothers = ["Holly", "Janelle", "Aniya", "Kailyn"]

    s = Solver()

    name_pos = {name: Int(f"name_{i}") for i, name in enumerate(names)}
    height_pos = {h: Int(f"height_{i}") for i, h in enumerate(heights)}
    drink_pos = {d: Int(f"drink_{i}") for i, d in enumerate(drinks)}
    child_pos = {c: Int(f"child_{i}") for i, c in enumerate(children)}
    mother_pos = {m: Int(f"mother_{i}") for i, m in enumerate(mothers)}

    for pos in (name_pos, height_pos, drink_pos, child_pos, mother_pos):
        s.add(Distinct([pos[k] for k in pos]))
        for k in pos:
            s.add(pos[k] >= 1, pos[k] <= 4)

    s.add(height_pos["tall"] == name_pos["Arnold"])
    s.add(child_pos["Samantha"] == drink_pos["tea"])
    s.add(mother_pos["Holly"] == drink_pos["coffee"])
    s.add(Abs(child_pos["Samantha"] - mother_pos["Holly"]) == 1)
    s.add(Abs(child_pos["Meredith"] - height_pos["very short"]) == 1)
    s.add(child_pos["Samantha"] == mother_pos["Aniya"])
    s.add(drink_pos["milk"] == height_pos["short"])
    s.add(name_pos["Alice"] == child_pos["Fred"])
    s.add(Abs(name_pos["Peter"] - height_pos["very short"]) == 1)
    s.add(drink_pos["coffee"] > child_pos["Samantha"])
    s.add(name_pos["Eric"] == height_pos["short"])
    s.add(mother_pos["Janelle"] < mother_pos["Kailyn"])
    s.add(name_pos["Alice"] == mother_pos["Kailyn"])
    s.add(child_pos["Meredith"] != 1)

    if s.check() != sat:
        return

    model = s.model()

    def attribute_at(pos_map, house):
        for attr, var in pos_map.items():
            if int(model.eval(var).as_long()) == house:
                return attr
        return "?"

    for house in range(1, 5):
        print(
            f"House {house}: "
            f"{attribute_at(name_pos, house)}, "
            f"{attribute_at(height_pos, house)}, "
            f"{attribute_at(drink_pos, house)}, "
            f"{attribute_at(child_pos, house)}, "
            f"{attribute_at(mother_pos, house)}"
        )

if __name__ == "__main__":
    main()

