from z3 import *

def main():
    categories = {
        "name": ["Eric", "Alice", "Arnold", "Peter"],
        "smoothie": ["cherry", "dragonfruit", "desert", "watermelon"],
        "color": ["green", "red", "yellow", "white"],
        "flower": ["roses", "carnations", "daffodils", "lilies"],
        "genre": ["fantasy", "science fiction", "mystery", "romance"],
    }

    pos = {}
    for cat, values in categories.items():
        pos[cat] = {}
        for value in values:
            var_name = f"{cat}_{value.replace(' ', '_')}_pos"
            pos[cat][value] = Int(var_name)

    s = Solver()

    for cat, values in categories.items():
        s.add(Distinct([pos[cat][value] for value in values]))
        for value in values:
            s.add(pos[cat][value] >= 0)
            s.add(pos[cat][value] <= 3)

    s.add(pos["genre"]["romance"] == pos["color"]["white"])
    s.add(pos["genre"]["fantasy"] == pos["flower"]["daffodils"])
    s.add(pos["smoothie"]["cherry"] < pos["genre"]["romance"])
    s.add(pos["genre"]["science fiction"] > pos["name"]["Peter"])
    s.add(pos["flower"]["lilies"] == pos["genre"]["science fiction"])
    s.add(pos["genre"]["romance"] != 3)
    s.add(pos["genre"]["fantasy"] == pos["smoothie"]["dragonfruit"])
    s.add(pos["color"]["white"] == pos["smoothie"]["desert"])
    s.add(pos["flower"]["carnations"] != 2)
    s.add(pos["name"]["Alice"] == pos["smoothie"]["cherry"])
    s.add(pos["name"]["Eric"] == pos["genre"]["mystery"])
    s.add(pos["color"]["green"] == 1)
    s.add(pos["color"]["yellow"] < pos["name"]["Eric"])

    if s.check() != sat:
        raise SystemExit("No solution found")

    model = s.model()
    assignment = {}

    for cat, values in categories.items():
        assignment[cat] = {}
        for value in values:
            house = model.eval(pos[cat][value]).as_long()
            assignment[cat][house] = value

    for house in range(4):
        print(
            f"House {house + 1}: "
            f"{assignment['name'][house]}, "
            f"{assignment['smoothie'][house]}, "
            f"{assignment['color'][house]}, "
            f"{assignment['flower'][house]}, "
            f"{assignment['genre'][house]}"
        )

if __name__ == "__main__":
    main()

