from z3 import *

def main():
    PETER, ERIC, ARNOLD = 0, 1, 2
    FORD, CAMRY, TESLA = 0, 1, 2

    s = Solver()

    names = [Int(f"name_{i}") for i in range(3)]
    cars = [Int(f"car_{i}") for i in range(3)]

    for i in range(3):
        s.add(names[i] >= 0, names[i] <= 2)
        s.add(cars[i] >= 0, cars[i] <= 2)

    s.add(Distinct(names))
    s.add(Distinct(cars))

    # Arnold is the person who owns a Tesla Model 3.
    for i in range(3):
        s.add(Implies(names[i] == ARNOLD, cars[i] == TESLA))
        s.add(Implies(cars[i] == TESLA, names[i] == ARNOLD))

    # Arnold and Peter are next to each other.
    for i in range(3):
        for j in range(3):
            s.add(
                Implies(
                    And(names[i] == ARNOLD, names[j] == PETER),
                    Or(i + 1 == j, i - 1 == j)
                )
            )

    # Arnold is in the first house.
    s.add(names[0] == ARNOLD)

    # The Toyota Camry is somewhere to the right of the Ford F-150.
    for i in range(3):
        for j in range(3):
            s.add(
                Implies(
                    And(cars[i] == CAMRY, cars[j] == FORD),
                    i > j
                )
            )

    if s.check() != sat:
        return

    m = s.model()

    name_to_str = {
        PETER: "Peter",
        ERIC: "Eric",
        ARNOLD: "Arnold"
    }

    car_to_str = {
        FORD: "ford f150",
        CAMRY: "toyota camry",
        TESLA: "tesla model 3"
    }

    for i in range(3):
        name_val = m.evaluate(names[i], model_completion=True).as_long()
        car_val = m.evaluate(cars[i], model_completion=True).as_long()
        print(f"House {i + 1}: {name_to_str[name_val]}, {car_to_str[car_val]}")

if __name__ == "__main__":
    main()

from z3 import *

N = 5

names = ["Arnold", "Peter", "Eric", "Alice", "Bob"]
hobbies = ["painting", "cooking", "knitting", "gardening", "photography"]
heights = ["very tall", "tall", "very short", "average", "short"]
lunches = ["stew", "grilled cheese", "stir fry", "spaghetti", "pizza"]

name_idx = {v: i for i, v in enumerate(names)}
hobby_idx = {v: i for i, v in enumerate(hobbies)}
height_idx = {v: i for i, v in enumerate(heights)}
lunch_idx = {v: i for i, v in enumerate(lunches)}

name = [Int(f"name_{i}") for i in range(N)]
hobby = [Int(f"hobby_{i}") for i in range(N)]
height = [Int(f"height_{i}") for i in range(N)]
lunch = [Int(f"lunch_{i}") for i in range(N)]

solver = Solver()

for i in range(N):
    solver.add(name[i] >= 0, name[i] < len(names))
    solver.add(hobby[i] >= 0, hobby[i] < len(hobbies))
    solver.add(height[i] >= 0, height[i] < len(heights))
    solver.add(lunch[i] >= 0, lunch[i] < len(lunches))

solver.add(Distinct(*name))
solver.add(Distinct(*hobby))
solver.add(Distinct(*height))
solver.add(Distinct(*lunch))

solver.add(Or(*[
    And(name[i] == name_idx["Bob"], hobby[i] == hobby_idx["photography"])
    for i in range(N)
]))

solver.add(Or(*[
    And(lunch[i] == lunch_idx["grilled cheese"], height[i] == height_idx["tall"])
    for i in range(N)
]))

solver.add(name[1] != name_idx["Peter"])

solver.add(Or(*[
    And(height[i] == height_idx["tall"], lunch[i + 1] == lunch_idx["stir fry"])
    for i in range(N - 1)
]))

solver.add(Or(*[
    And(hobby[i] == hobby_idx["cooking"], height[i] == height_idx["average"])
    for i in range(N)
]))

solver.add(Or(*[
    And(name[i] == name_idx["Alice"], lunch[i + 1] == lunch_idx["pizza"])
    for i in range(N - 1)
]))

solver.add(lunch[1] != lunch_idx["spaghetti"])

solver.add(name[4] != name_idx["Eric"])

solver.add(Or(*[
    And(height[i] == height_idx["short"], name[i] == name_idx["Peter"])
    for i in range(N)
]))

solver.add(Or(*[
    Or(
        And(height[i] == height_idx["average"], hobby[i + 1] == hobby_idx["gardening"]),
        And(height[i + 1] == height_idx["average"], hobby[i] == hobby_idx["gardening"])
    )
    for i in range(N - 1)
]))

solver.add(Or(*[
    And(hobby[i] == hobby_idx["painting"], lunch[i + 1] == lunch_idx["grilled cheese"])
    for i in range(N - 1)
]))

solver.add(height[4] == height_idx["very short"])

solver.add(height[2] == height_idx["tall"])

solver.add(Or(*[
    And(name[i] == name_idx["Alice"], hobby[j] == hobby_idx["photography"], i > j)
    for i in range(N)
    for j in range(N)
]))

if solver.check() == sat:
    m = solver.model()
    for i in range(N):
        n_val = m.eval(name[i], model_completion=True).as_long()
        h_val = m.eval(hobby[i], model_completion=True).as_long()
        ht_val = m.eval(height[i], model_completion=True).as_long()
        l_val = m.eval(lunch[i], model_completion=True).as_long()
        print(f"House {i + 1}: {names[n_val]}, {hobbies[h_val]}, {heights[ht_val]}, {lunches[l_val]}")
