from z3 import *

houses = range(6)

names = ["Alice", "Peter", "Arnold", "Bob", "Carol", "Eric"]
hairs = ["red", "brown", "blonde", "black", "gray", "auburn"]
jobs = ["engineer", "lawyer", "nurse", "doctor", "artist", "teacher"]

name_id = {n: i for i, n in enumerate(names)}
hair_id = {h: i for i, h in enumerate(hairs)}
job_id = {j: i for i, j in enumerate(jobs)}

name = [Int(f"name_{h}") for h in houses]
hair = [Int(f"hair_{h}") for h in houses]
job = [Int(f"job_{h}") for h in houses]

s = Solver()

for h in houses:
    s.add(name[h] >= 0, name[h] < len(names))
    s.add(hair[h] >= 0, hair[h] < len(hairs))
    s.add(job[h] >= 0, job[h] < len(jobs))

s.add(Distinct(*name))
s.add(Distinct(*hair))
s.add(Distinct(*job))

# 1. The person who has brown hair is not in the second house.
s.add(hair[1] != hair_id["brown"])

# 2. Alice is not in the fourth house.
s.add(name[3] != name_id["Alice"])

# 3. The person who is an artist is Bob.
for h in houses:
    s.add(Implies(name[h] == name_id["Bob"], job[h] == job_id["artist"]))
    s.add(Implies(job[h] == job_id["artist"], name[h] == name_id["Bob"]))

# 4. The person who has gray hair is the person who is a doctor.
for h in houses:
    s.add(Implies(hair[h] == hair_id["gray"], job[h] == job_id["doctor"]))
    s.add(Implies(job[h] == job_id["doctor"], hair[h] == hair_id["gray"]))

# 5. Bob is the person who has auburn hair.
for h in houses:
    s.add(Implies(name[h] == name_id["Bob"], hair[h] == hair_id["auburn"]))
    s.add(Implies(hair[h] == hair_id["auburn"], name[h] == name_id["Bob"]))

# 6. The person who is a doctor and Bob are next to each other.
s.add(Or([
    ((name[i] == name_id["Bob"]) & (job[i + 1] == job_id["doctor"])) |
    ((name[i + 1] == name_id["Bob"]) & (job[i] == job_id["doctor"]))
    for i in range(5)
]))

# 7. The person who is an engineer is directly left of Alice.
s.add(Or([
    (job[i] == job_id["engineer"]) & (name[i + 1] == name_id["Alice"])
    for i in range(5)
]))

# 8. Arnold is directly left of the person who is a lawyer.
s.add(Or([
    (name[i] == name_id["Arnold"]) & (job[i + 1] == job_id["lawyer"])
    for i in range(5)
]))

# 9. Bob is directly left of the person who is a teacher.
s.add(Or([
    (name[i] == name_id["Bob"]) & (job[i + 1] == job_id["teacher"])
    for i in range(5)
]))

# 10. Peter is somewhere to the right of the person who has brown hair.
s.add(Or([
    (name[p] == name_id["Peter"]) & (hair[b] == hair_id["brown"])
    for b in range(6)
    for p in range(b + 1, 6)
]))

# 11. Arnold is not in the second house.
s.add(name[1] != name_id["Arnold"])

# 12. The person who has black hair is Arnold.
for h in houses:
    s.add(Implies(hair[h] == hair_id["black"], name[h] == name_id["Arnold"]))
    s.add(Implies(name[h] == name_id["Arnold"], hair[h] == hair_id["black"]))

# 13. The person who is a doctor is somewhere to the right of the person who has red hair.
s.add(Or([
    (job[d] == job_id["doctor"]) & (hair[r] == hair_id["red"])
    for r in range(6)
    for d in range(r + 1, 6)
]))

# 14. The person who has brown hair and Carol are next to each other.
s.add(Or([
    ((hair[i] == hair_id["brown"]) & (name[i + 1] == name_id["Carol"])) |
    ((hair[i + 1] == hair_id["brown"]) & (name[i] == name_id["Carol"]))
    for i in range(5)
]))

# 15. Arnold is somewhere to the left of the person who is a doctor.
s.add(Or([
    (name[a] == name_id["Arnold"]) & (job[d] == job_id["doctor"])
    for a in range(6)
    for d in range(a + 1, 6)
]))

if s.check() == sat:
    m = s.model()

    def value(var):
        return m.eval(var, model_completion=True).as_long()

    for h in houses:
        print(f"House {h + 1}: {names[value(name[h])]}, {hairs[value(hair[h])]}, {jobs[value(job[h])]}")

